INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-ninjas-kick-back', 'Sega CD', '3 Ninjas Kick Back', '1994', 'Action', 'Konami', '2 Players', '2D', 'Side-scrolling action platformer with martial arts combat and weapon usage.', 'Navigate through levels to find the elderly ninja master and retrieve a sacred dagger.', 'A martial arts platformer based on the 1994 film featuring three young brothers.', 'Experience 3 Ninjas Kick Back on Sega CD, a classic action platformer where you master ninjutsu to defeat enemies and overcome obstacles in a quest to recover a stolen ceremonial dagger.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the', 'Sega CD', 'Adventures of Batman & Robin, The', '1995', 'Action', 'Clockwork Tortoise', '1 Player', '2D', 'Hybrid gameplay featuring vehicle-based shooter stages and side-scrolling action.', 'Stop Mr. Freeze, the Joker, and other villains from plunging Gotham City into chaos.', 'A high-octane action game featuring Batman and Robin with impressive pseudo-3D driving stages.', 'The Adventures of Batman & Robin for Sega CD delivers intense vehicular combat and platforming action. Fight through Gotham’s underworld in this visually stunning 16-bit era masterpiece based on the iconic animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-willy-beamish', 'Sega CD', 'Adventures of Willy Beamish', '1991', 'Adventure', 'Dynamix', '1 Player', 'Point-and-Click', 'Point-and-click graphic adventure with animated cutscenes and dialogue choices.', 'Navigate the life of a rebellious teenager while uncovering a town-wide conspiracy.', 'A humorous and detailed graphic adventure about the misadventures of a boy named Willy.', 'Dive into The Adventures of Willy Beamish on Sega CD. This interactive cartoon features branching storylines, hand-drawn animation, and a witty narrative that defines the golden age of point-and-click adventure gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('after-burner-iii', 'Sega CD', 'After Burner III', '1993', 'Shooter', 'Sega', '1 Player', '3D', 'Pseudo-3D cockpit-view flight combat simulator and rail shooter.', 'Engage in aerial dogfights and destroy enemy fleets across multiple missions.', 'An intense arcade flight combat game that pushes the Sega CD''s scaling capabilities.', 'After Burner III brings fast-paced arcade aerial combat to the Sega CD. Take control of advanced fighter jets and engage in high-speed dogfights in this definitive 16-bit flight simulator experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ah-3-thunderstrike', 'Sega CD', 'AH-3 Thunderstrike', '1992', 'Action', 'Sage''s Creation', '1 Player', '2D', 'Third-person 3D helicopter combat simulator with multiple mission objectives.', 'Complete various tactical military operations by destroying ground and air targets.', 'A groundbreaking 3D helicopter shooter featuring smooth scaling and intense combat.', 'AH-3 Thunderstrike is a premier combat flight sim for Sega CD. Pilot a heavily armed gunship through diverse warzones, utilizing advanced weaponry and tactical maneuvers in a fully realized 3D environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amazing-spider-man-the-vs-the-kingpin', 'Sega CD', 'Amazing Spider-Man, The vs. The Kingpin', '1994', 'Action', 'Technopop', '1 Player', '2D', 'Side-scrolling action-adventure with platforming and web-swinging mechanics.', 'Stop Kingpin from detonating a bomb in New York City by defeating several supervillains.', 'An enhanced version of the classic Spider-Man action game with CD-quality sound and cutscenes.', 'Play The Amazing Spider-Man vs. The Kingpin on Sega CD. Featuring animated sequences and a non-linear quest, this version offers the ultimate 16-bit superhero experience as you hunt for keys to disarm a nuclear threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('android-assault', 'Sega CD', 'Android Assault', '1992', 'Shooter', 'BlueSky Software', '1 Player', '2D', 'Vertical-scrolling shoot ''em up with transforming mecha mechanics.', 'Pilot a powerful spacecraft to repel an alien invasion and save humanity.', 'A fast-paced shmup with a heavy metal soundtrack and impressive sprite work.', 'Android Assault (The Revenge of Bari-Arm) is a must-play Sega CD shooter. Master the transforming mech system and blast through challenging stages accompanied by a high-energy CD audio soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('annet-futatabi', 'Sega CD', 'Annet Futatabi', '1993', 'Adventure', 'Fill-in-Cafe', '1 Player', 'Visual Novel', 'Side-scrolling hack-and-slash action with cinematic storytelling.', 'Battle through waves of enemies to protect a sacred artifact from an evil cult.', 'A Japanese-style cinematic brawler and sequel to El Viento, featuring fast combat.', 'Annet Futatabi delivers classic 16-bit hack-and-slash action on the Sega CD. Follow Annet’s journey in this visually driven adventure featuring large sprites, fluid animation, and an epic musical score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns', 'Sega CD', 'Batman Returns', '1992', 'Action', 'Konami', '1 Player', '2D', 'Action-oriented driving and side-scrolling brawler stages.', 'Defeat the Penguin and Catwoman to restore peace to Gotham City during Christmas.', 'A dark and atmospheric take on the film, combining vehicle levels and combat.', 'Batman Returns for Sega CD expands the classic gameplay with incredible "3D" driving levels and high-quality audio. Battle your way through Gotham in this definitive cinematic action experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlecorps', 'Sega CD', 'Battlecorps', '1994', 'Action', 'Core Design', '1 Player', '2D', 'First-person 3D tank combat simulator with strategic movement.', 'Complete various missions on a war-torn alien planet using a high-tech battle tank.', 'A gritty 3D tank shooter with industrial aesthetics and challenging combat.', 'Battlecorps offers an immersive 3D cockpit experience on the Sega CD. Navigate hostile terrain and engage in tactical armored warfare in this technically impressive 16-bit era combat simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bc-racers', 'Sega CD', 'BC Racers', '1994', 'Racing', 'Core Design', '1 Player', '3D', 'Prehistoric-themed racing game with pseudo-3D tracks and combat elements.', 'Compete in various Stone Age tracks to win the ultimate racing championship.', 'A quirky and fast-paced racing game from the creators of Chuck Rock.', 'BC Racers brings prehistoric speed to the Sega CD. Choose your caveman racer and navigate through hazardous 3D tracks filled with obstacles and rivals in this humor-filled racing adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bill-walsh-college-football', 'Sega CD', 'Bill Walsh College Football', '1993', 'Sports', 'Electronic Arts', '2 Players', '2D', 'American football sports simulation with realistic play-calling and stats.', 'Lead your chosen college football team to a national championship victory.', 'A comprehensive college football sim featuring CD-quality sound and FMV clips.', 'Bill Walsh College Football on Sega CD offers a deep sports simulation experience. With realistic team playbooks and enhanced audio, it remains a classic title for fans of 16-bit era gridiron action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackhole-assault', 'Sega CD', 'Blackhole Assault', '1993', 'Shooter', 'Software Creations', '1 Player', '2D', 'One-on-one fighting game featuring transforming robotic warriors.', 'Defeat a series of mechanical opponents to claim dominance in a futuristic tournament.', 'A unique sci-fi fighter where robots can change forms mid-battle.', 'Blackhole Assault combines traditional 2D fighting mechanics with a dark sci-fi aesthetic. Battle across the solar system in this Sega CD fighter featuring large robotic sprites and cinematic interludes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouncers', 'Sega CD', 'Bouncers', '1994', 'Action', 'Sega', '1 Player', '2D', 'Physics-based sports action game involving launching characters into targets.', 'Score points by accurately aiming and bouncing characters into specific zones.', 'A bizarre and colorful "combat basketball" style game with a heavy focus on physics.', 'Bouncers is one of the most unique titles on the Sega CD. Master the trajectory and timing of your bounces in this experimental sports-action hybrid that defies traditional genre conventions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bram-stokers-dracula', 'Sega CD', 'Bram Stoker''s Dracula', '1993', 'Action', 'Sony Imagesoft', '1 Player', '2D', 'Side-scrolling action-platformer with a focus on dark, atmospheric combat.', 'Hunt down the legendary vampire Dracula through various stages inspired by the film.', 'A cinematic platformer with digitized graphics and a haunting CD soundtrack.', 'Bram Stoker''s Dracula for Sega CD provides a dark, gothic atmosphere. Fight through levels filled with supernatural creatures in this cinematic adaptation featuring high-quality audio and digitized visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brutal---paws-of-fury', 'Sega CD', 'Brutal - Paws of Fury', '1994', 'Fighting', 'Eurocom', '2 Players', '2D', 'One-on-one fighting game featuring anthropomorphic animals with diverse styles.', 'Defeat all challengers in a martial arts tournament to prove your animal spirit.', 'A colorful 2D fighter known for its quirky characters and fluid animation.', 'Brutal: Paws of Fury brings "animalistic" combat to the Sega CD. Learn new moves as you progress through the tournament in this unique fighter featuring a standout CD-quality soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('championship-soccer-94', 'Sega CD', 'Championship Soccer ''94', '1994', 'Sports', 'Sensory Sweep Studios', '2 Players', '2D', 'Traditional top-down soccer simulation with tournament and exhibition modes.', 'Outscore your opponents to win the international soccer championship.', 'A fast-paced soccer game featuring various international teams and smooth gameplay.', 'Championship Soccer ''94 on Sega CD offers classic 16-bit sports action. With multiple camera angles and realistic physics for its time, it provides a solid football experience for retro gaming fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock', 'Sega CD', 'Chuck Rock', '1991', 'Platform', 'Taura', '1 Player', '2D', 'Side-scrolling platformer with a focus on belly-bumping combat.', 'Rescue your wife Ophelia from the clutches of a rival caveman named Gary.', 'A humorous prehistoric platformer starring a lovable, beer-bellied caveman.', 'Chuck Rock on Sega CD delivers classic platforming fun with an iconic rock-and-roll soundtrack. Use your belly to bash enemies and solve environmental puzzles in this stone-age adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-ii---son-of-chuck', 'Sega CD', 'Chuck Rock II - Son Of Chuck', '1993', 'Platform', 'Core Design', '1 Player', '2D', 'Side-scrolling platformer featuring a baby with a club as the protagonist.', 'Rescue your father, Chuck Rock, from the evil Brick Jagger.', 'The high-energy sequel to Chuck Rock, featuring more refined gameplay and humor.', 'Chuck Rock II: Son of Chuck improves on the original with better graphics and faster action. Play as Junior in this prehistoric quest filled with secret areas and challenging boss fights on Sega CD.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger', 'Sega CD', 'Cliffhanger', '1993', 'Action', 'Malibu Interactive', '1 Player', '2D', 'Side-scrolling action and cinematic quick-time event sequences.', 'Survive the mountain and defeat a gang of terrorists to rescue hostages.', 'An action-platformer based on the Stallone movie, featuring FMV sequences.', 'Cliffhanger on Sega CD blends traditional 2D combat with cinematic FMV transitions. Scale frozen peaks and fight through mercenaries in this high-stakes adventure based on the blockbuster film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cobra-command', 'Sega CD', 'Cobra Command', '1993', 'Shooter', 'Data East', '1 Player', 'FMV', 'Full-motion video (FMV) rail shooter featuring helicopter combat.', 'Navigate through enemy territory and destroy targets to complete flight missions.', 'A classic arcade port that uses real video footage for its background and action.', 'Cobra Command is a hallmark of the Sega CD''s FMV library. Pilot your attack chopper through intense live-action sequences and test your reflexes in this fast-paced cinematic shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('corpse-killer-usa', 'Sega CD', 'Corpse Killer (USA)', '1994', 'Shooter', 'Digital Pictures', '1 Player', 'FMV', 'FMV light-gun shooter set on a tropical island infested with vampires.', 'Use a specialized weapon to neutralize vampires and uncover a dark mystery.', 'A cult classic FMV shooter featuring live-action actors and horror themes.', 'Corpse Killer on Sega CD is a quintessential 90s FMV experience. Hunt the undead in this tropical horror-shooter featuring campy acting and intense light-gun style gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazysonic---super-ultra-cool-bodacious-radical-mega-cd-remastered-edition!!!-european-version', 'Sega CD', 'CrazySonic - Super Ultra Cool Bodacious Radical Mega CD Remastered Edition!!! (European Version)', '2017', 'Platformer', 'Frogbull', '1 Player', '2D', 'High-speed 2D side-scrolling platformer with remastered audio and visuals.', 'Collect rings and defeat Dr. Robotnik to save the flickies and the world.', 'A fan-favorite community remaster of Sonic CD with enhanced features for Europe.', 'CrazySonic (European Version) brings the ultimate Sonic CD experience to your Sega CD. Enjoy optimized gameplay, a legendary soundtrack, and the iconic speed of the Blue Blur in this remastered edition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazysonic---super-ultra-cool-bodacious-radical-mega-cd-remastered-edition!!!-japanese-version', 'Sega CD', 'CrazySonic - Super Ultra Cool Bodacious Radical Mega CD Remastered Edition!!! (Japanese Version)', '2017', 'Platformer', 'Frogbull', '1 Player', '2D', 'High-speed 2D side-scrolling platformer with remastered audio and visuals.', 'Collect rings and defeat Dr. Robotnik to save the flickies and the world.', 'The Japanese edition of the remastered Sonic CD experience with regional tweaks.', 'CrazySonic (Japanese Version) offers the definitive Eastern take on the Sonic CD remaster. Featuring the original JP/EU soundtrack and refined mechanics, it''s a masterpiece of 16-bit platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazysonic---super-ultra-cool-bodacious-radical-mega-cd-remastered-edition!!!-usa-version', 'Sega CD', 'CrazySonic - Super Ultra Cool Bodacious Radical Mega CD Remastered Edition!!! (USA Version)', '2017', 'Platformer', 'Frogbull', '1 Player', '2D', 'High-speed 2D side-scrolling platformer with remastered audio and visuals.', 'Collect rings and defeat Dr. Robotnik to save the flickies and the world.', 'The North American edition of the remastered Sonic CD experience.', 'CrazySonic (USA Version) delivers high-speed action with the remastered American soundtrack. Experience the "Super Ultra Cool" definitive version of Sonic''s CD debut with enhanced technical performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crime-patrol', 'Sega CD', 'Crime Patrol', '1994', 'Shooter', 'Digital Pictures', '1 Player', 'FMV', 'FMV light-gun shooter featuring live-action police investigations.', 'Pursue and apprehend criminals in various high-stakes scenarios as a rookie cop.', 'A cinematic rail shooter that puts you in the shoes of a police officer.', 'Crime Patrol on Sega CD uses live-action video to create an immersive law enforcement simulation. Test your aim and decision-making skills in this classic 90s FMV shooting gallery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dark-wizard', 'Sega CD', 'Dark Wizard', '1993', 'Strategy', 'Sega', '1 Player', '2D', 'Tactical turn-based RPG with grid-based combat and deep story elements.', 'Command an army to reclaim a lost kingdom from the forces of darkness.', 'A massive and highly-rated strategy RPG featuring high-quality CD music.', 'Dark Wizard is a crown jewel of the Sega CD strategy library. With four different protagonists and branching paths, it offers hundreds of hours of tactical gameplay and deep fantasy world-building.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('demolition-man', 'Sega CD', 'Demolition Man', '1995', 'Action', 'Virgin Interactive', '1 Player', '2D', 'Side-scrolling action-platformer with explosive combat and shooting.', 'Hunt down the villainous Simon Phoenix in a futuristic, dystopian city.', 'A high-octane action game based on the film, featuring CD-quality audio.', 'Demolition Man on Sega CD captures the intensity of the movie. Blast your way through futuristic levels using a variety of weapons in this challenging and visually impressive 2D shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-lair', 'Sega CD', 'Dragon''s Lair', '1991', 'Action', 'Bluth Group', '1 Player', 'Animated', 'Full-motion video (FMV) quick-time event adventure game.', 'Navigate a treacherous castle to rescue Princess Daphne from a dragon.', 'The legendary arcade laserdisc game brought to home consoles with FMV.', 'Dragon''s Lair on Sega CD is a faithful port of the animated classic. Use precise timing to guide Dirk the Daring through a series of deadly traps in this groundbreaking cinematic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dune', 'Sega CD', 'Dune', '1992', 'Strategy', 'Cryo Interactive', '1 Player', '2D', 'Strategy and adventure hybrid with resource management and exploration.', 'Command the forces of House Atreides to control the spice and conquer Arrakis.', 'A deep and atmospheric adaptation of the classic sci-fi novel.', 'Dune on Sega CD combines exploration, conversation, and grand strategy. Experience the struggle for Arrakis with an incredible ambient soundtrack and voiced dialogue that brings the desert planet to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-explorer', 'Sega CD', 'Dungeon Explorer', '1994', 'Action RPG', 'Hudson Soft', '2 Players', '2D', 'Top-down action RPG with cooperative multiplayer support.', 'Choose a hero class to explore dungeons and defeat the ancient demon Natas.', 'A fantasy action-adventure featuring multiple classes and intense boss battles.', 'Dungeon Explorer on Sega CD brings classic 16-bit dungeon crawling to life. With enhanced CD audio and frantic multiplayer action, it’s a premier title for fans of fantasy RPGs and cooperative gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-master-ii', 'Sega CD', 'Dungeon Master II', '1993', 'RPG', 'FTL Games', '1 Player', '2D', 'First-person dungeon crawler with real-time combat and environmental puzzles.', 'Explore a multi-level dungeon to stop an evil wizard from summoning a dark god.', 'A deep, atmospheric sequel to the genre-defining first-person RPG.', 'Dungeon Master II: The Legend of Skullkeep for Sega CD offers an immersive RPG experience. Manage your party''s resources and solve intricate puzzles in this technically advanced dungeon simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earnest-evans', 'Sega CD', 'Earnest Evans', '1993', 'Action', 'Wow Entertainment', '1 Player', '2D', 'Side-scrolling action-platformer featuring a whip-wielding protagonist.', 'Travel the globe to prevent the resurrection of an ancient, chaotic deity.', 'A fast-paced action game known for its unique multi-jointed character sprites.', 'Earnest Evans on Sega CD features cinematic cutscenes and a high-energy soundtrack. Master the whip mechanics and navigate physics-based platforming in this cult classic action adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim---special-edition', 'Sega CD', 'Earthworm Jim - Special Edition', '1995', 'Platformer', 'Shiny Entertainment', '1 Player', '2D', 'Side-scrolling platformer with surreal art design and run-and-gun mechanics.', 'Navigate bizarre worlds to rescue Princess What''s-Her-Name from Queen Slug-for-a-Butt.', 'The definitive version of the classic game with expanded levels and CD audio.', 'Earthworm Jim Special Edition on Sega CD is the ultimate way to play this 90s icon. Featuring CD-quality music, extra levels, and improved animations, it’s a masterpiece of run-and-gun comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco---the-tides-of-time', 'Sega CD', 'Ecco - The Tides Of Time', '1994', 'Action', 'Novotrade', '1 Player', '2D', 'Atmospheric underwater adventure with puzzle-solving and exploration.', 'Travel through time to save the ocean''s future from the Vortex menace.', 'A visually stunning sequel featuring advanced pseudo-3D flight sequences.', 'Ecco: The Tides of Time on Sega CD delivers an ethereal experience with a mesmerizing soundtrack. Explore vast oceanic environments and master new transformations in this epic sci-fi sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin', 'Sega CD', 'Ecco the Dolphin', '1993', 'Action', 'Novotrade', '1 Player', '2D', 'Underwater exploration and action-adventure with a focus on sonar mechanics.', 'Rescue your pod from an alien abduction and defeat the Vortex Queen.', 'A groundbreaking title known for its difficulty, beauty, and unique premise.', 'Ecco the Dolphin on Sega CD enhances the original experience with a legendary ambient soundtrack and high-quality video sequences, making it the most immersive version of Ecco’s first journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-nba-hangtime-95', 'Sega CD', 'ESPN NBA Hangtime ''95', '1995', 'Sports', 'Midway', '2 Players', '2D', 'Professional basketball simulation with realistic player stats and FMV.', 'Compete in a full NBA season and lead your team to the championship.', 'A sports sim featuring real NBA players and CD-quality broadcast audio.', 'ESPN NBA Hangtime ''95 for Sega CD offers a deep basketball experience. With updated rosters for the era and realistic TV-style presentation, it’s a staple for 16-bit sports enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-champions---challenge-from-the-dark-side', 'Sega CD', 'Eternal Champions - Challenge from the Dark Side', '1995', 'Fighting', 'Sega', '2 Players', '2D', 'One-on-one 2D fighting game with a massive roster and violent finishers.', 'Win the tournament to save the future of humanity from the Dark Champion.', 'An expanded version of the Genesis hit with new characters and FMV kills.', 'Eternal Champions: Challenge from the Dark Side is the definitive Sega CD fighter. Featuring brutal "Cine-Kill" finishers and a deep combat system, it’s a dark and technical fighting masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eye-of-the-beholder---advanced-dungeons-&-dragons', 'Sega CD', 'Eye of the Beholder - Advanced Dungeons & Dragons', '1994', 'RPG', 'Westwood Studios', '1 Player', '2D', 'First-person grid-based RPG based on the AD&D ruleset.', 'Explore the sewers and dungeons beneath Waterdeep to slay the beholder Xanathar.', 'A faithful adaptation of the classic D&D tabletop experience.', 'Eye of the Beholder on Sega CD features a fully voiced intro and a revamped soundtrack. Experience the gold standard of 90s dungeon crawling with this deep, tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-special', 'Sega CD', 'Fatal Fury Special', '1994', 'Fighting', 'SNK', '2 Players', '2D', 'High-speed 2D fighting game with a large roster of SNK characters.', 'Defeat the world''s strongest fighters to prove your dominance in the tournament.', 'A refined arcade port featuring massive sprites and a CD-quality soundtrack.', 'Fatal Fury Special on Sega CD brings the arcade intensity home. Execute complex combos and special moves in this definitive 16-bit port of the legendary SNK fighting franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer', 'Sega CD', 'Fifa International Soccer', '1994', 'Sports', 'Electronic Arts', '2 Players', '2D', 'Isometric soccer simulation with realistic physics and crowd noise.', 'Lead your national team to victory in the international soccer tournament.', 'The game that started the FIFA legacy, enhanced with CD audio and FMV.', 'FIFA International Soccer on Sega CD offers a stadium-like atmosphere. Experience the roar of the crowd and refined gameplay in this early milestone of sports gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-cd', 'Sega CD', 'Final Fight CD', '1993', 'Beat ''em up', 'Capcom', '2 Players', '2D', 'Side-scrolling beat ''em up featuring three unique playable characters.', 'Fight through the streets of Metro City to rescue the Mayor''s daughter.', 'An incredible port of the arcade classic with an iconic CD soundtrack.', 'Final Fight CD is widely considered the best home version of the arcade hit. Battle the Mad Gear Gang with high-fidelity music and fully voiced cinematic sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback---the-quest-for-identity', 'Sega CD', 'Flashback - The Quest for Identity', '1993', 'Action', 'Delphine Software', '1 Player', '2D', 'Cinematic action-platformer with a focus on rotoscoped animation.', 'Recover your lost memories and stop an alien conspiracy to save Earth.', 'A sci-fi masterpiece known for its fluid animation and deep story.', 'Flashback on Sega CD features enhanced FMV cutscenes and high-quality audio. Navigate complex environments and engage in tactical combat in this legendary cinematic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heart-of-the-alien---out-of-this-world-part-i-&-ii', 'Sega CD', 'Heart of the Alien - Out of this World Part I & II', '1994', 'Adventure', 'Interplay', '1 Player', '2D', 'Cinematic adventure platformer featuring two full games in one.', 'Help Lester and his alien friend Buddy survive a hostile alien planet.', 'The sequel to Out of This World, bundled with the original masterpiece.', 'Heart of the Alien for Sega CD is the only way to play the direct sequel to the iconic Out of This World, featuring enhanced CD visuals and a gripping sci-fi narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heimdall', 'Sega CD', 'Heimdall', '1994', 'RPG', 'Core Design', '1 Player', '2D', 'Isometric action-adventure based on Norse mythology.', 'Embark on a quest as the young Viking Heimdall to retrieve the gods'' weapons.', 'A unique blend of exploration, combat, and Norse-themed puzzles.', 'Heimdall on Sega CD brings an epic Viking saga to life. Navigate a vast world and complete legendary trials in this atmospheric adventure featuring enhanced audio and visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook', 'Sega CD', 'Hook', '1992', 'Action', 'Ocean Software', '1 Player', '2D', 'Side-scrolling action-platformer based on the Spielberg film.', 'Journey through Neverland to rescue your children from Captain Hook.', 'A colorful adventure featuring digitized images and music from the film.', 'Hook on Sega CD allows you to live the movie experience. Fight through pirates and mythical creatures in this polished platformer featuring high-quality CD sound and cinematic stills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jaguar-xj220', 'Sega CD', 'Jaguar XJ220', '1993', 'Racing', 'Tatsumi', '1 Player', '3D', 'High-speed racing simulation featuring the iconic Jaguar XJ220.', 'Compete in a global racing tour to become the world champion driver.', 'A technical racing masterpiece with a built-in track editor and CD music.', 'Jaguar XJ220 on Sega CD offers incredibly smooth pseudo-3D racing. Customize your experience with the track editor and enjoy one of the best soundtracks in the 16-bit racing genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy-!', 'Sega CD', 'Jeopardy !', '1994', 'Trivia', 'GameTek', '2 Players', '2D', 'Quiz show simulation based on the popular TV program.', 'Answer trivia questions across various categories to win the most money.', 'A digital version of the famous game show featuring a digitized Alex Trebek.', 'Jeopardy! on Sega CD brings the TV studio home. Test your knowledge with thousands of questions and enjoy the authentic sights and sounds of the legendary quiz show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montanas-nfl-football', 'Sega CD', 'Joe Montana''s NFL Football', '1994', 'Sports', 'Electronic Arts', '2 Players', '2D', 'American football simulation with FMV coaching tips.', 'Lead your team to victory in the Super Bowl with help from Joe Montana.', 'A sports title featuring real-life video clips and professional commentary.', 'Joe Montana''s NFL Football on Sega CD uses the power of the disc format to include digitized speech and video, offering a more broadcast-like feel than its cartridge counterparts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park', 'Sega CD', 'Jurassic Park', '1994', 'Action', 'Sega', '1 Player', '2D', 'Point-and-click adventure game with a focus on exploration and puzzles.', 'Survive the dinosaur-infested park and find a way to escape the island.', 'A dark and atmospheric adventure featuring 360-degree panoramic views.', 'Jurassic Park on Sega CD is a unique take on the franchise. Focus on survival and environmental puzzle-solving in this immersive, first-person exploration game with high-quality audio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keio-flying-squadron', 'Sega CD', 'Keio Flying Squadron', '1993', 'Shooter', 'Victor Interactive', '1 Player', '2D', 'Side-scrolling shoot ''em up with a quirky, anime-inspired aesthetic.', 'Pilot a flying dragon to stop an evil general from seizing a powerful artifact.', 'A beautiful and humorous shmup known for its high production values.', 'Keio Flying Squadron is a rare gem on the Sega CD. Featuring stunning hand-drawn animations and a fantastic soundtrack, it is one of the most charming and sought-after shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-on-site', 'Sega CD', 'Kids On Site', '1994', 'Adventure', 'Sega', '1 Player', 'FMV', 'Full-motion video (FMV) interactive construction game for kids.', 'Operate heavy machinery to complete various tasks on a busy construction site.', 'A fun, interactive video experience designed for younger players.', 'Kids on Site on Sega CD puts you in the driver’s seat of real bulldozers and cranes. Interact with live-action characters in this unique and educational FMV adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lawnmower-man-the', 'Sega CD', 'Lawnmower Man, The', '1994', 'Action', 'Virgin Interactive', '1 Player', 'FMV', 'Cyberpunk action game featuring first-person shooting and 3D flight.', 'Enter virtual reality to defeat the god-like entity known as Jobe.', 'A genre-mashing title based on the cult classic sci-fi film.', 'The Lawnmower Man on Sega CD utilizes FMV and 3D scaling to recreate the film''s virtual reality world. Experience a mix of gameplay styles in this ambitious technological showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers', 'Sega CD', 'Lethal Enforcers', '1993', 'Shooter', 'Konami', '2 Players', 'FMV', 'First-person light-gun rail shooter featuring digitized graphics.', 'Take down criminals in various urban scenarios as a legendary police officer.', 'The definitive home port of the arcade classic with CD-quality audio.', 'Lethal Enforcers on Sega CD brings the arcade light-gun experience home. Use the Justifier peripheral to blast through high-stakes missions in this iconic 90s shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lethal-enforcers-ii---gun-fighters', 'Sega CD', 'Lethal Enforcers II - Gun Fighters', '1994', 'Shooter', 'Konami', '2 Players', 'FMV', 'First-person light-gun rail shooter with a Western theme.', 'Protect a frontier town from outlaws and bandits in the Old West.', 'A cinematic sequel to the original hit, featuring digitized cowboys.', 'Lethal Enforcers II: Gun Fighters on Sega CD offers intense Wild West action. Blast your way through saloons and stagecoaches in this high-fidelity arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lords-of-thunder', 'Sega CD', 'Lords of Thunder', '1993', 'Shooter', 'Compile', '1 Player', '2D', 'Side-scrolling shoot ''em up with heavy metal music and RPG elements.', 'Defeat the four elemental generals to save the kingdom of Avelu.', 'An intense, fast-paced shmup with one of the best soundtracks on the system.', 'Lords of Thunder is a legendary Sega CD title. Combine frantic shooting action with a shop system and a blistering heavy metal soundtrack for an unforgettable 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar---the-silver-star', 'Sega CD', 'Lunar - The Silver Star', '1993', 'RPG', 'Game Arts', '1 Player', '2D', 'Traditional turn-based Japanese RPG with high-quality anime cutscenes.', 'Guide Alex on his quest to become a Dragonmaster and save the world.', 'A beloved RPG classic known for its heart, story, and incredible music.', 'Lunar: The Silver Star on Sega CD set the standard for cinematic storytelling in RPGs. Experience an emotional journey with fully voiced cutscenes and a timeless orchestrated soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar-2---eternal-blue', 'Sega CD', 'Lunar 2 - Eternal Blue', '1994', 'RPG', 'Game Arts', '1 Player', '2D', 'Turn-based JRPG with expanded world-building and cinematic sequences.', 'Follow Hiro and Lucia on an epic quest to stop an ancient evil from returning.', 'The massive sequel to Silver Star, featuring improved graphics and sound.', 'Lunar 2: Eternal Blue is a masterpiece of the Sega CD era. With a deep combat system and hours of hand-drawn anime sequences, it is often cited as one of the greatest RPGs of all time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mad-dog-mccree', 'Sega CD', 'Mad Dog McCree', '1993', 'Shooter', 'American Laser Games', '1 Player', 'FMV', 'Full-motion video (FMV) light-gun shooter in a Western setting.', 'Defeat the outlaw Mad Dog McCree to save the town and the mayor''s daughter.', 'A classic arcade laserdisc port featuring live-action actors and sets.', 'Mad Dog McCree on Sega CD brings the frontier to life. Test your reflexes in this cinematic shooting gallery that defined the FMV genre in the early 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mad-dog-mccree-ii---the-lost-gold', 'Sega CD', 'Mad Dog McCree II - The Lost Gold', '1994', 'Shooter', 'American Laser Games', '1 Player', 'FMV', 'FMV light-gun shooter with multiple paths and hidden treasures.', 'Race against rivals to find a stash of lost gold in the Old West.', 'The live-action sequel with higher production values and more shooting action.', 'Mad Dog McCree II: The Lost Gold expands the FMV shooting experience on Sega CD. Navigate branching paths and take down outlaws in this high-stakes search for legendary treasure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mansion-of-hidden-souls', 'Sega CD', 'Mansion of Hidden Souls', '1993', 'Adventure', 'Sega', '1', 'FMV adventure', 'First-person exploration and puzzle-solving adventure.', 'Navigate a mysterious mansion to find your sister and unravel a supernatural mystery.', 'A haunting atmospheric adventure featuring 3D-style navigation and FMV.', 'Mansion of Hidden Souls on Sega CD offers a ghostly, immersive experience. Explore detailed rooms and solve environmental puzzles in this early cinematic masterpiece of the horror genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-shelleys-frankenstein', 'Sega CD', 'Mary Shelley''s Frankenstein', '1994', 'Action-adventure', 'Bits Studios', '1', 'Cinematic action adventure', 'Side-scrolling action-adventure with a dark, gothic art style.', 'Survive the frozen wilderness and confront your creator in a final showdown.', 'A moody platformer based on the 1994 film with high-quality CD audio.', 'Mary Shelley''s Frankenstein brings the classic horror tale to Sega CD. Battle through atmospheric levels featuring digitized visuals and a haunting orchestrated soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('masked-rider-the---kamen-rider-zo', 'Sega CD', 'Masked Rider, The - Kamen Rider Zo', '1993', 'Beat ''em up', 'Sega', '1', 'Side-scrolling brawler', 'Full-motion video (FMV) interactive action game with timing-based combat.', 'Defeat the Neo Organoid and its mutant henchmen to save the world.', 'An FMV experience based on the Japanese Kamen Rider Zo movie.', 'The Masked Rider for Sega CD features high-speed cinematic combat. Master your timing to unleash powerful strikes in this live-action superhero adventure from the Tokusatsu universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mania---the-timeless-adventures-of-mickey-mouse', 'Sega CD', 'Mickey Mania - The Timeless Adventures of Mickey Mouse', '1994', 'Platformer', 'Traveller''s Tales', '1', 'Animated platformer', 'Side-scrolling platformer featuring levels based on classic Disney shorts.', 'Traverse through Mickey’s cinematic history to reach the modern era.', 'A beautiful platformer enhanced for Sega CD with extra stages and audio.', 'Mickey Mania: The Timeless Adventures on Sega CD is the definitive version of this classic. Experience Mickey''s evolution with CD-quality sound and exclusive graphical enhancements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers', 'Sega CD', 'Mighty Morphin Power Rangers', '1994', 'Beat ''em up', 'Natsume', '1', 'Side-scrolling brawler', 'Full-motion video (FMV) quick-time event action game.', 'Defeat Rita Repulsa’s monsters by following the on-screen prompts.', 'An interactive episode of the hit TV show using actual video footage.', 'Mighty Morphin Power Rangers for Sega CD lets you control the Rangers in a cinematic format. Time your button presses to fight iconic villains in this live-action 90s classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('misadventures-of-flink-the', 'Sega CD', 'Misadventures of Flink, The', '1994', 'Platformer', 'Psygnosis', '1', 'Action platformer', 'Side-scrolling platformer with a complex alchemy and crafting system.', 'Use magic and platforming skills to defeat the wicked wizard and save the land.', 'A visually stunning platformer from the creators of Lomax and Rayman.', 'The Misadventures of Flink on Sega CD showcases incredible 2D sprite work. Collect ingredients to brew spells and explore a lush fantasy world in this technical 16-bit marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat', 'Sega CD', 'Mortal Kombat', '1993', 'Fighting', 'Midway', '1-2', 'Fighting game', 'One-on-one fighting game with digitized fighters and violent fatalities.', 'Defeat Shang Tsung and his fighters to win the Mortal Kombat tournament.', 'The most faithful 16-bit port of the arcade hit, featuring the original soundtrack.', 'Mortal Kombat on Sega CD delivers the ultimate home experience of the arcade phenomenon. Featuring CD-quality audio and the uncensored blood code, it''s a retro fighting essential.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam', 'Sega CD', 'NBA Jam', '1994', 'Sports', 'Iguana Entertainment', '1-2', 'Arcade basketball', 'Two-on-two arcade-style basketball with high-flying dunks and power-ups.', 'Outscore your opponents in fast-paced matches to become the world champion.', 'The legendary arcade basketball game featuring real NBA teams and players.', 'NBA Jam for Sega CD brings "He''s on fire!" to your console with enhanced audio and gameplay. Experience the fast-paced, gravity-defying action of 90s arcade basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('novastorm', 'Sega CD', 'Novastorm', '1994', 'Shooter', 'Psygnosis', '1', 'Rail shooter', 'Pseudo-3D rail shooter with futuristic environments and boss battles.', 'Pilot a high-tech starship to destroy a rogue AI and its robotic army.', 'A visually spectacular shooter utilizing pre-rendered 3D video backgrounds.', 'Novastorm on Sega CD is a graphical tour de force. Blast through alien worlds in this cinematic shooter featuring high-quality FMV and a pulsing electronic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panic-!', 'Sega CD', 'Panic !', '1992', 'Puzzle', 'Sega', '1', 'Arcade puzzle action', 'Humorous puzzle-adventure with interactive FMV sequences.', 'Navigate through bizarre rooms and solve surreal puzzles to progress.', 'A quirky and surreal cult classic from Japan featuring wacky animations.', 'Panic! for Sega CD is a unique experience that blends humor with puzzle-solving. Explore a weird digital world where every button press leads to a hilarious and unexpected outcome.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penn-&-tellers-smoke-and-mirrors', 'Sega CD', 'Penn & Teller''s Smoke and Mirrors', '1995', 'Party', 'Absolute Entertainment', '1-2', 'Mini-game collection', 'A collection of mini-games and prank tools disguised as a video game.', 'Use the "Smoke and Mirrors" tricks to prank your friends and family.', 'An unreleased cult classic featuring the famous magicians and their wit.', 'Penn & Teller''s Smoke and Mirrors is a legendary Sega CD title. From the infamous "Desert Bus" to satirical mini-games, it’s a masterclass in comedic game design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pitfall---the-mayan-adventure', 'Sega CD', 'Pitfall - The Mayan Adventure', '1994', 'Platformer', 'Activision', '1', 'Action platformer', 'Side-scrolling action-platformer with jungle exploration and puzzles.', 'Search for your father and recover a lost Mayan treasure in the rainforest.', 'An updated version of the classic franchise with CD-quality music.', 'Pitfall: The Mayan Adventure on Sega CD offers refined platforming and lush environments. Navigate dangerous ruins and avoid deadly traps in this high-fidelity 16-bit journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popful-mail---magical-fantasy-adventure', 'Sega CD', 'Popful Mail - Magical Fantasy Adventure', '1994', 'Action RPG', 'Nihon Falcom', '1', 'Anime-style action RPG', 'Side-scrolling action-RPG with a focus on humor and character dialogue.', 'Help the bounty hunter Mail stop an evil wizard while making a profit.', 'A charming and funny JRPG with high-quality anime cutscenes and voices.', 'Popful Mail for Sega CD is a fan favorite. Featuring an incredible English dub and tight platform-action gameplay, it’s one of the most charismatic RPGs on the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-monger', 'Sega CD', 'Power Monger', '1993', 'Strategy', 'Bullfrog Productions', '1', 'God game strategy', 'Real-time strategy and simulation with a god-like perspective.', 'Conquer territories and manage resources to unify the world under your rule.', 'A port of Bullfrog’s classic strategy game featuring expanded CD audio.', 'Power Monger on Sega CD provides a deep tactical experience. Command armies and manage logistics in this complex 16-bit simulation from the creators of Populous.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia', 'Sega CD', 'Prince of Persia', '1993', 'Platformer', 'Broderbund', '1', 'Cinematic platformer', 'Cinematic platformer with rotoscoped animation and time-based puzzles.', 'Navigate a trap-filled dungeon to rescue the Princess within 60 minutes.', 'The definitive 16-bit version of the classic with a new CD soundtrack.', 'Prince of Persia for Sega CD revamps the classic adventure with a beautiful orchestrated score and enhanced visuals, while maintaining the legendary difficulty and fluid movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puggsy', 'Sega CD', 'Puggsy', '1993', 'Puzzle platformer', 'Traveller''s Tales', '1', 'Physics-based platformer', 'Physics-based puzzle-platformer starring a quirky alien protagonist.', 'Collect magical items and defeat the space pirates to find your way home.', 'A clever and creative platformer where you use objects to solve puzzles.', 'Puggsy on Sega CD features an incredible soundtrack and smart physics mechanics. Use various tools to manipulate your environment in this underrated 16-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('racing-aces', 'Sega CD', 'Racing Aces', '1993', 'Racing', 'Sega', '1-2', 'Arcade racing', 'First-person 3D air-racing game with multiple planes and tracks.', 'Compete in high-speed aerial races to become the champion of the skies.', 'A technical showcase featuring impressive 3D scaling and flight physics.', 'Racing Aces for Sega CD offers a unique perspective on the racing genre. Choose your aircraft and master the skies in this fast-paced, technically advanced 16-bit flight game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('radical-rex', 'Sega CD', 'Radical Rex', '1994', 'Platformer', 'Beam Software', '1', 'Action platformer', 'Side-scrolling platformer starring a skateboarding, fire-breathing dinosaur.', 'Rescue your girlfriend and save your fellow dinosaurs from extinction.', 'A quirky and fast-paced platformer with a distinct 90s "radical" attitude.', 'Radical Rex on Sega CD brings prehistoric fun with a high-energy soundtrack. Skate, shout, and breath fire through vibrant levels in this colorful action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ranma-12---byakuranaika-japan', 'Sega CD', 'Ranma 1/2 - Byakuranaika (Japan)', '1994', 'Adventure', 'Rumic Soft', '1', 'Visual novel adventure', 'Digital comic and turn-based adventure game based on the anime series.', 'Follow Ranma Saotome through a series of comedic and supernatural events.', 'A Japan-exclusive adventure game featuring the original voice cast.', 'Ranma 1/2: Byakuranaika for Sega CD is a treat for anime fans. Experience the humor and action of the series through high-quality CD audio and detailed character art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revenge-of-the-ninja', 'Sega CD', 'Revenge of the Ninja', '1993', 'Action', 'Sega', '1', 'Ninja action', 'Full-motion video (FMV) quick-time event action game.', 'Use ninja skills and quick reflexes to defeat a series of deadly assassins.', 'A classic arcade laserdisc port featuring hand-drawn animation.', 'Revenge of the Ninja on Sega CD puts you in the role of a master ninja. Follow the cinematic prompts to survive high-stakes encounters in this legendary animated FMV title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revengers-of-vengeance', 'Sega CD', 'Revengers of Vengeance', '1993', 'Shooter', 'Sega', '1', 'Top-down shooter', 'Hybrid fighting game and RPG with a dark fantasy setting.', 'Fight in tournaments to earn money and power to defeat an ancient evil.', 'A unique blend of Street Fighter-style combat and RPG character growth.', 'Revengers of Vengeance for Sega CD offers a deep and unusual experience. Train your character and engage in intense 2D battles in this ambitious genre-mashing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-dragon', 'Sega CD', 'Rise of the Dragon', '1993', 'Adventure', 'Dynamix', '1', 'FMV adventure', 'First-person point-and-click adventure with a cyberpunk aesthetic.', 'Solve a series of murders and uncover a corporate conspiracy in a future city.', 'A gritty, neon-soaked adventure with deep storytelling and voice acting.', 'Rise of the Dragon for Sega CD is a hallmark of the cyberpunk genre. Navigate a dark future through detailed artwork and immersive cinematic sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-avenger', 'Sega CD', 'Road Avenger', '1993', 'Action', 'Wolf Team', '1', 'FMV action', 'Full-motion video (FMV) interactive driving and combat game.', 'Pursue and destroy a criminal biker gang in high-speed car chases.', 'A high-octane animated FMV game known for its speed and energy.', 'Road Avenger (Road Blaster) on Sega CD is an anime action classic. Experience a feature-length interactive movie where your steering and reflexes determine your survival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash', 'Sega CD', 'Road Rash', '1994', 'Racing', 'Electronic Arts', '1-2', 'Combat racing', 'Combat-oriented motorcycle racing with a rock and roll soundtrack.', 'Race across the USA while fighting off rival bikers and avoiding the police.', 'The definitive version of the first game, featuring a full CD soundtrack.', 'Road Rash on Sega CD enhances the classic motorcycle brawler with high-quality music and video intros, delivering the ultimate 16-bit street-racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robo-aleste', 'Sega CD', 'Robo Aleste', '1993', 'Shooter', 'Compile', '1', 'Vertical shooter', 'Vertical-scrolling shoot ''em up with a steampunk feudal Japan theme.', 'Pilot a robotic warrior to stop an evil clan from taking over the world.', 'A visually stunning shmup featuring massive bosses and smooth action.', 'Robo Aleste on Sega CD is a masterpiece of the genre. With an incredible soundtrack and intense bullet-hell gameplay, it stands as one of the best shooters of the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-shodown', 'Sega CD', 'Samurai Shodown', '1994', 'Fighting', 'SNK', '1-2', 'Weapon-based fighting', 'One-on-one fighting game with weapon-based combat and large sprites.', 'Master your weapon and defeat the world''s greatest warriors in feudal Japan.', 'An arcade-perfect port featuring high-fidelity sound and scaling effects.', 'Samurai Shodown for Sega CD brings the SNK classic home with style. Experience the tension of weapon-based duels with the benefit of a CD-quality soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-of-monkey-island-the', 'Sega CD', 'Secret of Monkey Island, The', '1992', 'Adventure', 'LucasArts', '1', 'Point-and-click adventure', 'Point-and-click graphic adventure featuring a wannabe pirate.', 'Solve puzzles and outsmart the ghost pirate LeChuck to find the secret.', 'The legendary adventure game updated with CD audio and a new interface.', 'The Secret of Monkey Island on Sega CD is the best way to play the original. Featuring the iconic Red Book audio soundtrack, it brings Guybrush Threepwood’s first quest to life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-classics---4-in-1', 'Sega CD', 'Sega Classics - 4-in-1', '1994', 'Compilation', 'Sega', '1-2', 'Game compilation', 'A collection of classic Sega titles in one disc.', 'Relive the arcade and console glory days with multiple classic games.', 'A compilation featuring titles like Golden Axe, Streets of Rage, and Shinobi.', 'Sega Classics 4-in-1 provides a curated selection of the system''s best. Enjoy these 16-bit essentials with the convenience of a single Sega CD disc.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-classics---5-in-1', 'Sega CD', 'Sega Classics - 5-in-1', '1994', 'Compilation', 'Sega', '1-2', 'Game compilation', 'An expanded collection of classic Sega titles on a single disc.', 'Experience a variety of Sega’s greatest hits in a revamped format.', 'Includes Golden Axe, Streets of Rage, Shinobi, Columns, and Super Monaco GP.', 'Sega Classics 5-in-1 is the ultimate starter disc for Sega CD. Featuring a wide range of genres, it’s a perfect showcase of the Genesis era’s best gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seima-densetsu-3x3-eyes-japan-korea', 'Sega CD', 'Seima Densetsu 3x3 Eyes (Japan, Korea)', '1994', 'RPG', 'System Sacom', '1', 'Anime-style RPG', 'Turn-based RPG and digital comic based on the 3x3 Eyes manga.', 'Follow the journey of Yakumo and the immortal Pai across the globe.', 'A visually driven JRPG with high-quality cinematics and voice work.', 'Seima Densetsu 3x3 Eyes on Sega CD is an immersive adaptation of the beloved manga. Experience the epic supernatural story with enhanced CD audio and detailed art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sewer-shark', 'Sega CD', 'Sewer Shark', '1992', 'Shooter', 'Digital Pictures', '1', 'FMV rail shooter', 'First-person FMV rail shooter set in a subterranean tunnel system.', 'Pilot a "Holehog" craft and exterminate mutant sewer creatures to reach Solar City.', 'A flagship FMV title for the Sega CD featuring digitized video and fast reflexes.', 'Sewer Shark on Sega CD is a quintessential 90s FMV experience. Navigate a post-apocalyptic underground world, follow co-pilot instructions, and blast enemies in this cinematic shooting classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-of-the-beast-ii', 'Sega CD', 'Shadow of the Beast II', '1992', 'Action platformer', 'Reflections Interactive', '1', 'Dark fantasy platformer', 'Side-scrolling action-adventure with a heavy emphasis on puzzle-solving.', 'Avenge your father and rescue your sister from the evil Zelek.', 'A dark, atmospheric fantasy adventure known for its high difficulty and art style.', 'Shadow of the Beast II for Sega CD enhances the Psygnosis classic with an incredible CD soundtrack and cinematic FMV. Explore a hostile alien world in this visually striking 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-cd', 'Sega CD', 'Shining Force CD', '1994', 'Strategy RPG', 'Sonic! Software Planning', '1', 'Tactical role-playing game', 'Turn-based tactical RPG with grid-based combat and party management.', 'Lead the Force to defeat the forces of Iom and save the kingdom of Guardiana.', 'A massive compilation featuring remakes of the Game Gear titles and new scenarios.', 'Shining Force CD is a premier tactical RPG experience. Command a diverse army in epic strategic battles, featuring enhanced CD-quality music and refined 16-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silpheed', 'Sega CD', 'Silpheed', '1993', 'Shooter', 'Game Arts', '1', '3D space shooter', 'Vertical-scrolling shoot ''em up using polygon-based pseudo-3D graphics.', 'Pilot the SA-77 Silpheed starship to destroy a terrorist supercomputer.', 'A technical marvel for the system featuring pre-rendered 3D backgrounds.', 'Silpheed on Sega CD delivers intense space combat with a cinematic feel. Experience one of the most visually ambitious shooters of the era, backed by a powerful orchestral score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-the', 'Sega CD', 'Smurfs, The', '1994', 'Platformer', 'Infogrames', '1', 'Cartoon platformer', 'Side-scrolling platformer based on the famous Belgian comic characters.', 'Travel through various environments to rescue captured Smurfs from Gargamel.', 'A colorful and charming platformer with enhanced CD audio and visuals.', 'The Smurfs on Sega CD brings the beloved characters to life with vibrant 16-bit graphics and high-fidelity sound. Navigate through forests and mountains in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('snatcher', 'Sega CD', 'Snatcher', '1994', 'Adventure', 'Konami', '1', 'Cyberpunk graphic adventure', 'Cyberpunk point-and-click adventure with interactive investigation elements.', 'Hunt down humanoid bioroids known as "Snatchers" in the city of Neo Kobe.', 'Hideo Kojima’s legendary sci-fi masterpiece with full voice acting and FMV.', 'Snatcher for Sega CD is a cult classic of the highest order. Immerse yourself in a deep, adult-oriented narrative featuring incredible world-building, music, and cinematic presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sol-feace', 'Sega CD', 'Sol-Feace', '1993', 'Shooter', 'Wolf Team', '1', 'Arcade space shooter', 'Horizontal-scrolling shoot ''em up with a focus on weapon power-ups.', 'Pilot a futuristic fighter to prevent an ancient alien race from taking over.', 'A fast-paced arcade-style shooter that was a launch title for the system.', 'Sol-Feace on Sega CD features an amazing rock-and-roll soundtrack that enhances the shooting action. Master multiple weapon systems to survive waves of galactic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-1-mega-cd-port', 'Sega CD', 'Sonic 1 Mega CD Port', '1993', 'Platformer', 'Sega', '1', 'Classic platformer', 'High-speed side-scrolling platformer (port of the original Genesis game).', 'Collect Chaos Emeralds and defeat Dr. Robotnik to save South Island.', 'A technical port of the first Sonic game optimized for the Sega CD hardware.', 'Sonic 1 Mega CD Port brings the original 1991 classic to the CD format. Enjoy the iconic platforming gameplay with the stability and loading benefits of the Sega CD system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-europe', 'Sega CD', 'Sonic CD (Europe)', '1993', 'Platformer', 'Sega', '1', 'Classic platformer', 'High-speed 2D platformer featuring time-travel mechanics.', 'Travel between past, present, and future to stop Metal Sonic and save Amy Rose.', 'The European version of the iconic game featuring the JP/EU soundtrack.', 'Sonic CD (Europe) is a platforming legend. Utilize time travel to explore different versions of every stage, accompanied by the acclaimed original electronic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-japan', 'Sega CD', 'Sonic CD (Japan)', '1993', 'Platformer', 'Sega', '1', 'Classic platformer', 'High-speed 2D platformer featuring time-travel mechanics.', 'Travel between past, present, and future to stop Metal Sonic and save Amy Rose.', 'The original Japanese release featuring the legendary synth-pop soundtrack.', 'Sonic CD (Japan) offers the definitive Eastern experience of Sonic’s CD debut. Master the Spin Dash and Super Peel-Out in this critically acclaimed 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-usa', 'Sega CD', 'Sonic CD (USA)', '1993', 'Platformer', 'Sega', '1', 'Classic platformer', 'High-speed 2D platformer featuring time-travel mechanics.', 'Travel between past, present, and future to stop Metal Sonic and save Amy Rose.', 'The North American version featuring an entirely unique rock/blues soundtrack.', 'Sonic CD (USA) delivers the same great time-traveling action with a distinct atmospheric soundtrack composed specifically for the American market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-plus-plus', 'Sega CD', 'Sonic CD Plus Plus', '2019', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Modified high-speed 2D platformer with various quality-of-life improvements.', 'Complete stages across time while enjoying bug fixes and new features.', 'A fan-enhanced version of Sonic CD designed to polish the original experience.', 'Sonic CD Plus Plus is a refined take on the classic. Enjoy smoother gameplay and technical adjustments that make this one of the best ways to experience the game today.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-plus-plus-jp-version', 'Sega CD', 'Sonic CD Plus Plus (JP version)', '2019', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Modified high-speed 2D platformer with improvements and the original OST.', 'Complete stages across time while enjoying bug fixes and the JP soundtrack.', 'The Japanese-flavored version of the Plus Plus fan modification.', 'Sonic CD Plus Plus (JP version) combines the technical refinements of the Plus Plus mod with the iconic Japanese synth-pop audio tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-warped-v100-europe', 'Sega CD', 'Sonic CD Warped V1.0.0 (Europe)', '2020', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Modified 2D platformer with revamped physics and new gameplay secrets.', 'Explore the time-traveling world of Sonic CD with modern fan-made tweaks.', 'A European-based mod that alters the core experience for veteran players.', 'Sonic CD Warped V1.0.0 (Europe) offers a fresh perspective on the 16-bit classic. Discover new secrets and tuned mechanics in this comprehensive fan-led overhaul.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-warped-v100-japan', 'Sega CD', 'Sonic CD Warped V1.0.0 (Japan)', '2020', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Modified 2D platformer with revamped physics and new gameplay secrets.', 'Explore the time-traveling world of Sonic CD with modern fan-made tweaks.', 'A Japanese-based mod that alters the core experience for veteran players.', 'Sonic CD Warped V1.0.0 (Japan) brings the Warped overhaul to the original JP audio experience, offering a unique challenge for hardcore Sonic enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-warped-v100-usa', 'Sega CD', 'Sonic CD Warped V1.0.0 (USA)', '2020', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Modified 2D platformer with revamped physics and new gameplay secrets.', 'Explore the time-traveling world of Sonic CD with modern fan-made tweaks.', 'A USA-based mod that alters the core experience for veteran players.', 'Sonic CD Warped V1.0.0 (USA) combines the North American soundtrack with the extensive "Warped" gameplay modifications for a new way to play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-cd-with-the-original-jump-sound', 'Sega CD', 'Sonic CD with the Original Jump Sound', '2018', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'High-speed 2D platformer with a minor audio modification.', 'Save the world from Dr. Robotnik while using the original 8-bit jump sound.', 'A specialized version of Sonic CD featuring a nostalgic sound effect swap.', 'Sonic CD with the Original Jump Sound is a treat for fans of the 8-bit master system games, integrating classic audio into the high-tech CD environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-for-megacd', 'Sega CD', 'Sonic for MegaCD', '2019', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'Side-scrolling platformer port of the original Sonic experience.', 'Defeat Dr. Robotnik and free the animals on South Island.', 'A community-driven port of Sonic 1 specifically for the Sega CD hardware.', 'Sonic for MegaCD provides a stable and high-quality way to play the first Sonic game, taking advantage of the CD hardware for improved loading and data handling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-megamix-50', 'Sega CD', 'Sonic Megamix 5.0', '2017', 'Platformer', 'Fan-made', '1', 'Fan remake', 'High-speed 2D platformer featuring multiple playable characters and new levels.', 'Navigate a massive world with Sonic, Tails, Knuckles, and more.', 'One of the most famous Sonic mods, featuring professional-grade new content.', 'Sonic Megamix 5.0 on Sega CD is a monumental achievement in the fan community. Experience new zones, music, and abilities that push the Sega CD to its absolute limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-1-for-segacd', 'Sega CD', 'Sonic the Hedgehog 1 for SegaCD', '2018', 'Platformer', 'Fan-made', '1', 'Fan remake', 'Side-scrolling platformer port of the original Sonic the Hedgehog.', 'Collect the Chaos Emeralds and stop Robotnik''s schemes on South Island.', 'A dedicated port of the first game designed for the Sega CD''s architecture.', 'Sonic the Hedgehog 1 for SegaCD offers a crisp and efficient way to play the 1991 classic on the CD add-on, maintaining the speed that defined a generation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-cd-aug-1-1993-prototype', 'Sega CD', 'Sonic the Hedgehog CD (Aug 1, 1993 prototype)', '1993', 'Platformer', 'Sega', '1', 'Prototype platformer', 'High-speed 2D platformer (unfinished early development version).', 'Explore early iterations of stages and mechanics from the development phase.', 'An extremely early prototype of Sonic CD, providing a look at "Work in Progress" art.', 'Sonic the Hedgehog CD (Aug 1, 1993 prototype) is a piece of gaming history, allowing players to see how the game evolved just months before its final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-cd-dec-4-1992-prototype', 'Sega CD', 'Sonic the Hedgehog CD (Dec 4, 1992 prototype)', '1992', 'Platformer', 'Sega', '1', 'Prototype platformer', 'High-speed 2D platformer (extremely early development version).', 'Navigate primitive versions of zones and test early physics.', 'A very rare look at the infancy of Sonic CD''s development cycle.', 'Sonic the Hedgehog CD (Dec 4, 1992 prototype) offers a fascinating glimpse into the early design choices and cut content from the beginning of the project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-cd-jun-21-1993-prototype', 'Sega CD', 'Sonic the Hedgehog CD (Jun 21, 1993 prototype)', '1993', 'Platformer', 'Sega', '1', 'Prototype platformer', 'High-speed 2D platformer (mid-development prototype version).', 'Explore stages with different layouts and unused musical cues.', 'A prototype version that shows significant progress toward the final game.', 'Sonic the Hedgehog CD (Jun 21, 1993 prototype) is famous among fans for its unique differences in level design and audio compared to the retail version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-cd-may-12-1993-prototype', 'Sega CD', 'Sonic the Hedgehog CD (May 12, 1993 prototype)', '1993', 'Platformer', 'Sega', '1', 'Prototype platformer', 'High-speed 2D platformer (early-mid development prototype version).', 'Test the time-travel mechanics in their earlier, less refined state.', 'A development build that captures the transition between early concepts and the final game.', 'Sonic the Hedgehog CD (May 12, 1993 prototype) allows players to explore the "Little Planet" in a state of flux, featuring numerous technical curiosities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-megamix-40b', 'Sega CD', 'Sonic the Hedgehog Megamix 4.0b', '2016', 'Platformer', 'Fan-made', '1', 'Modified platformer', 'High-speed 2D platformer with revamped levels and multiple characters.', 'Save the world using an expanded roster of heroes and new moves.', 'An earlier version of the legendary Megamix mod with its own unique charm.', 'Sonic the Hedgehog Megamix 4.0b is a fan-favorite iteration of the mod, offering a high-speed challenge that feels like a brand new 16-bit Sonic game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soul-star', 'Sega CD', 'Soul Star', '1994', 'Shooter', 'Core Design', '1', 'Top-down shooter', 'Third-person 3D shooter with flight and ground-based combat.', 'Pilot a transforming craft to liberate a star system from alien invaders.', 'A technical powerhouse for the Sega CD featuring impressive 3D scaling.', 'Soul Star is one of the most visually impressive games on the system. Master flight, hover, and walking modes in this epic space opera with a grand cinematic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-ace', 'Sega CD', 'Space Ace', '1994', 'Action', 'Digital Leisure', '1', 'Interactive cartoon FMV', 'Full-motion video (FMV) quick-time event adventure game.', 'Navigate a futuristic space station to rescue Kimberly from Borf.', 'Don Bluth’s legendary animated arcade game ported to the Sega CD.', 'Space Ace on Sega CD features high-quality hand-drawn animation. Use lightning-fast reflexes to guide Dexter through a series of comedic and dangerous cinematic trials.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-adventure-the---cobra-the-legendary-bandit', 'Sega CD', 'Space Adventure, The - Cobra the Legendary Bandit', '1993', 'Adventure', 'Hudson Soft', '1', 'Anime adventure', 'Point-and-click graphic adventure based on the cult anime series.', 'Join the space pirate Cobra on an epic quest to find hidden treasure.', 'A cinematic adventure featuring full voice acting and comic-book style art.', 'The Space Adventure on Sega CD is a rare gem for anime fans. Follow Cobra’s journey through a high-stakes sci-fi world, featuring a great dub and atmospheric CD audio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-blade', 'Sega CD', 'Star Blade', '1991', 'Shooter', 'Namco', '1', '3D arcade shooter', 'First-person rail shooter with 3D polygon graphics.', 'Pilot the FX-01 GeoSword to destroy the Red Eye planet and the Octopass fleet.', 'A stunning arcade port featuring high-speed space combat and 3D visuals.', 'Star Blade on Sega CD brings the cinematic arcade experience home. Engage in intense intergalactic dogfights with smooth scaling and a powerful sci-fi soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars---rebel-assault', 'Sega CD', 'Star Wars - Rebel Assault', '1993', 'Shooter', 'LucasArts', '1', 'FMV rail shooter', 'First-person FMV rail shooter and flight combat.', 'Pilot an X-Wing and other craft to defeat the Galactic Empire.', 'A cinematic Star Wars experience featuring digitized movie footage and music.', 'Star Wars: Rebel Assault on Sega CD brings the movie magic home. Battle TIE fighters and navigate asteroid fields in this immersive FMV shooter with iconic John Williams audio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-chess', 'Sega CD', 'Star Wars Chess', '1993', 'Board game', 'Sculptured Software', '1-2', 'Strategy board game', 'Traditional chess simulation with animated combat sequences.', 'Checkmate the opponent''s King using characters from the Star Wars universe.', 'A themed chess game featuring iconic heroes and villains as playing pieces.', 'Star Wars Chess for Sega CD transforms the classic board game into a cinematic battle. Watch Luke, Vader, and others duel in high-quality animations during every capture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stellar-fire', 'Sega CD', 'Stellar-Fire', '1993', 'Shooter', 'Dynamix', '1', 'Arcade space shooter', 'First-person 3D tank combat and exploration.', 'Pilot a high-tech hovercraft to destroy alien threats across multiple planets.', 'A technically impressive 3D shooter featuring smooth scaling and fast action.', 'Stellar-Fire on Sega CD offers a cockpit-view combat experience like no other. Navigate hostile alien terrains and engage in tactical 3D warfare with a pulsing CD soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate', 'Sega CD', 'Syndicate', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'Isometric tactical squad-based strategy and simulation.', 'Lead a team of cyborg agents to complete missions for global corporate dominance.', 'A gritty cyberpunk strategy game with deep management and combat.', 'Syndicate on Sega CD delivers a dark futuristic simulation. Manage your corporation’s research and deploy heavily armed agents in tactical missions across a dystopian world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the', 'Sega CD', 'Terminator, The', '1993', 'Action', 'Gray Matter', '1', 'Cinematic action platformer', 'Side-scrolling action-platformer with a focus on gun combat.', 'Survive the present and the future to prevent the rise of the machines.', 'A dark and atmospheric action game based on the iconic sci-fi film.', 'The Terminator on Sega CD features an incredible industrial rock soundtrack. Fight through levels filled with Skynet’s hunters in this definitive 16-bit cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-park', 'Sega CD', 'Theme Park', '1994', 'Simulation', 'Bullfrog Productions', '1', 'Theme park management sim', 'Business simulation and management strategy game.', 'Build and manage a successful theme park to earn maximum profit.', 'A deep and humorous sim that allows you to design your own attractions.', 'Theme Park for Sega CD brings the classic Bullfrog sim to life with enhanced audio. Manage everything from salt levels in fries to rollercoaster speeds in this addictive tycoon game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('third-world-war', 'Sega CD', 'Third World War', '1994', 'Strategy', 'Rage Software', '1', 'Modern warfare strategy', 'Grand strategy and global political simulation.', 'Manage your nation''s economy and military to achieve world supremacy.', 'A complex geopolitical sim featuring deep tactical and economic layers.', 'Third World War on Sega CD offers a comprehensive look at global conflict. Negotiate with world leaders and command armies in this sophisticated strategy masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-gal', 'Sega CD', 'Time Gal', '1993', 'Action', 'Taito', '1', 'Anime-style FMV action', 'Full-motion video (FMV) quick-time event adventure.', 'Travel through different time periods to stop a futuristic criminal.', 'A classic animated laserdisc port featuring a time-traveling protagonist.', 'Time Gal on Sega CD is a vibrant animated adventure. Use quick reflexes to guide Reika through history’s most dangerous eras in this fan-favorite FMV classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultraverse-prime', 'Sega CD', 'Ultraverse Prime', '1994', 'Action', 'Iguana Entertainment', '1', 'Superhero action platformer', 'Side-scrolling beat ''em up and platformer.', 'Use superhero powers to defeat villains and uncover a dark conspiracy.', 'An action game based on the Malibu Comics character with FMV cutscenes.', 'Ultraverse Prime on Sega CD combines traditional brawler action with comic book storytelling. Experience the power of Prime in this high-energy 16-bit superhero adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('urusei-yatsura---dear-my-friends-japan', 'Sega CD', 'Urusei Yatsura - Dear My Friends (Japan)', '1994', 'Adventure', 'Headroom', '1', 'Anime visual novel', 'Point-and-click graphic adventure based on the classic anime.', 'Interact with Ataru and Lum to navigate a series of comedic scenarios.', 'A beautifully animated Japan-exclusive adventure for fans of the series.', 'Urusei Yatsura: Dear My Friends brings the iconic anime to Sega CD. Explore detailed locations and enjoy fully voiced dialogue from the original Japanese cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vay', 'Sega CD', 'Vay', '1994', 'RPG', 'Sims', '1', 'Classic console RPG', 'Traditional turn-based Japanese RPG with cinematic cutscenes.', 'Journey across the world of Vay to stop an invading mechanical empire.', 'A classic JRPG featuring high-quality anime sequences and a deep story.', 'Vay on Sega CD is an essential RPG for the platform. Experience an epic tale of magic and technology featuring a fully orchestrated soundtrack and hours of gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune', 'Sega CD', 'Wheel of Fortune', '1994', 'Quiz', 'GameTek', '1-2', 'Game show trivia', 'Quiz show simulation based on the long-running TV program.', 'Spin the wheel and solve word puzzles to win virtual cash and prizes.', 'A digital version of the hit game show featuring Vanna White.', 'Wheel of Fortune on Sega CD provides an authentic TV experience. Compete against friends or AI in this high-fidelity adaptation of the world’s most famous game show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-shot-johnny-rock', 'Sega CD', 'Who Shot Johnny Rock', '1994', 'Action', 'Digital Pictures', '1', 'FMV interactive movie', 'Full-motion video (FMV) light-gun rail shooter.', 'Investigate the murder of a musician by interrogating suspects and shooting.', 'A cinematic detective mystery set in a gritty urban environment.', 'Who Shot Johnny Rock? on Sega CD tests your aim and your brain. Navigate this live-action interactive movie to find the killer in a campy, fun 90s FMV experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-woody', 'Sega CD', 'Wild Woody', '1994', 'Platformer', 'Electronic Arts', '1', 'Cartoon action platformer', 'Side-scrolling platformer featuring a living pencil.', 'Navigate through drawings and sketches to rescue your creator.', 'A quirky and technically impressive platformer with high-quality FMV.', 'Wild Woody on Sega CD is a unique 16-bit title where you use drawings to solve puzzles. Explore vibrant worlds with a sarcastic protagonist and a catchy CD soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander', 'Sega CD', 'Wing Commander', '1994', 'Shooter', 'Origin Systems', '1', 'Space combat shooter', 'First-person space combat flight simulator.', 'Pilot a starfighter to defend the Terran Confederation against the Kilrathi.', 'A legendary space opera featuring branching paths and cinematic audio.', 'Wing Commander on Sega CD offers an immersive cockpit experience. Engage in intense dogfights and influence the war’s outcome in this genre-defining space sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfchild', 'Sega CD', 'Wolfchild', '1993', 'Platformer', 'Core Design', '1', 'Action platformer', 'Side-scrolling action-platformer with transformation mechanics.', 'Rescue your father from a high-tech facility by turning into a werewolf.', 'A fast-paced action game featuring a unique wolf-transformation system.', 'Wolfchild on Sega CD enhances the original experience with cinematic intros and a fantastic soundtrack. Battle through mutant-filled levels using powerful lycanthropic abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-dog', 'Sega CD', 'Wonder Dog', '1993', 'Platformer', 'Core Design', '1', 'Colorful action platformer', 'Side-scrolling platformer featuring a heroic dog with a boomerang.', 'Rescue your planet from an invading army of space aliens.', 'A charming and colorful platformer that served as an early mascot for the system.', 'Wonder Dog for Sega CD is a polished and fun 16-bit adventure. Navigate imaginative worlds and defeat quirky bosses in this family-friendly action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-usa-94', 'Sega CD', 'World Cup USA 94', '1994', 'Sports', 'U.S. Gold', '1-2', 'Soccer arcade sports', 'Top-down soccer simulation with tournament and league modes.', 'Lead your national team to victory in the 1994 FIFA World Cup.', 'The official game of the 1994 tournament featuring CD-quality audio.', 'World Cup USA 94 on Sega CD captures the spirit of the international tournament. With realistic sound effects and stadium atmosphere, it''s a classic for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-rage-in-the-cage', 'Sega CD', 'WWF Rage in the Cage', '1993', 'Wrestling', 'Acclaim', '1-2', 'Arcade-style wrestling', 'One-on-one professional wrestling with digitized footage.', 'Defeat a roster of WWF legends to win the heavyweight championship.', 'A wrestling game featuring 20 superstars and real FMV footage.', 'WWF Rage in the Cage is the first wrestling game to use the CD format. Featuring high-quality audio and digitized finishers, it’s a must-play for 90s wrestling fans.');